export function buildDemoSeed(base){const extra=[{via:"Plaza de Cervantes, 12",codigoPostal:"28801",localidad:"Alcalá de Henares",provincia:"Madrid",pais:"España",coordenadas:[-3.3643513,40.4818074]},{via:"Plaza Mayor, 1",codigoPostal:"28100",localidad:"Alcobendas",provincia:"Madrid",pais:"España",coordenadas:[-3.6419688,40.5475472]},{via:"Plaza de la Constitución, 1",codigoPostal:"28901",localidad:"Getafe",provincia:"Madrid",pais:"España",coordenadas:[-3.73257,40.3055499]}];const capital=base.filter(c=>c.direccion.coordenadas&&c.direccion.localidad==="Madrid").map(c=>c.direccion);if(!capital.length)throw Error("Faltan direcciones de referencia.");const first=["Lucía","Álvaro","María","Javier","Elena","Diego","Carmen","Sergio","Laura","Andrés","Pilar","Rubén","Sara","Hugo","Nuria","Víctor","Raquel","David","Irene","Manuel"];const surnames=["García","Martín","López","Sánchez","Pérez","Romero","Navarro","Torres","Gil","Serrano","Moreno","Vega","Ramos","Ortiz","Molina","Marín","Castro","Delgado"];const equipos=["Caldera Bosch Condens 2300i","Caldera Vaillant ecoTEC","Caldera Saunier Duval Thema","Calentador Junkers Hydronext","Caldera Baxi Neodens"];const out=[];for(let i=0;i<360;i++){const month=Math.floor(i/120),year=month===2?2027:2026,m=month===2?1:11+month,days=new Date(Date.UTC(year,m,0)).getUTCDate(),day=1+(i*7%days),due=`${year}-${String(m).padStart(2,"0")}-${String(day).padStart(2,"0")}`;const address=structuredClone(i%5<2?extra[Math.floor(i/5)%extra.length]:capital[(i*7)%capital.length]);address.pisoPuerta=`Unidad ficticia ${1+Math.floor(i/30)}`;const id=`DEMO-${String(i+1).padStart(4,"0")}`;const availability=i%11===0?{weekdays:[2,4]}:i%13===0?{weekdays:[1,3,5]}:{};if(i%17===0)availability.from=due;if(i%19===0)availability.excluded=[due];out.push({id,nombre:`${first[i%first.length]} ${surnames[Math.floor(i/first.length)%surnames.length]} ${surnames[(i*7+3)%surnames.length]}`,telefono:`+34 900 ${String(i+200000).slice(0,3)} ${String(i+200000).slice(3)}`,email:`${id.toLowerCase()}@example.com`,direccion:address,fechaAlta:`2022-03-${String(1+i%28).padStart(2,"0")}`,equipo:equipos[i%equipos.length],revisiones:[{fecha:`${year-2}${due.slice(4)}`,descripcion:"Revisión anual y comprobación de combustión."},{fecha:`${year-1}${due.slice(4)}`,descripcion:i%3?"Limpieza de quemador y comprobación de seguridad.":"Revisión del intercambiador y ajuste de presión."}],demoPlan:{duration:[30,45,60,90,120][i%5],availability,preset:i%31===0,confirmed:i%2===0},demoSource:"Referencias públicas de bibliotecas y ayuntamientos; personas y unidades ficticias."});}return out;}
